generate.POST.yml
{periodName}
# Generate one period per calendar month from the from-date's month to the to-date's month, each named yyyy-mm and
# running from the first to the last day of its month. A month whose name is already a period, or whose days overlap
# a period on the sheet, is left out. A refused generate (bad dates, to before from, unknown sheet) writes nothing.
validate:
  class: net.officefloor.hq.app.period.ValidatePeriodGenerate
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.period.SaveGeneratedPeriods
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.AuditPeriodsGenerated
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriodsGenerated
  govern: [ transaction ]
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.YearMonth;
import java.time.format.DateTimeParseException;
import java.time.temporal.ChronoUnit;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: from and to real yyyy-mm-dd dates, from on or
 *  before to, and no more than MAX_MONTHS months. */
public class ValidatePeriodGenerate {

    static final int MAX_MONTHS = 1200;

    public void validate(@RequestBody PeriodGenerateRequest request, Out<PeriodGenerateInput> body)
            throws InvalidPeriodException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPeriodException("Sign in before generating periods.");
        }
        LocalDate from = date(request.from(), "from");
        LocalDate to = date(request.to(), "to");
        if (to.isBefore(from)) {
            throw new InvalidPeriodException("The to-date must not be before the from-date.");
        }
        YearMonth first = YearMonth.from(from);
        YearMonth last = YearMonth.from(to);
        if (first.until(last, ChronoUnit.MONTHS) >= MAX_MONTHS) {
            throw new InvalidPeriodException("Generate at most " + MAX_MONTHS + " months at once.");
        }
        body.set(new PeriodGenerateInput(request.user().trim(), first, last));
    }

    private static LocalDate date(String text, String which) throws InvalidPeriodException {
        try {
            return LocalDate.parse(text == null ? "" : text.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidPeriodException("The " + which + "-date must be a date, yyyy-mm-dd.");
        }
    }
}
package net.officefloor.hq.app.period;

import java.time.YearMonth;

/** A validated period generate: who is making it, and the first and last month (first on or before last). */
public record PeriodGenerateInput(String user, YearMonth first, YearMonth last) {
}
package net.officefloor.hq.app.period;

/** Body of a period generate: who is making it, and the from and to dates (yyyy-mm-dd). */
public record PeriodGenerateRequest(String user, String from, String to) {
}
package net.officefloor.hq.app.period;

import java.util.List;

/** The periods a generate made, in month order. */
public record GeneratedPeriods(List<Period> periods) {
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Add a yyyy-mm period for each month first..last, leaving out a month whose name is already a period on the
 *  sheet (without regard to case) or whose days overlap a period on the sheet. */
public class SaveGeneratedPeriods {
    public void save(@PathVariable("sheetId") String sheetId, @Val PeriodGenerateInput input,
            PeriodRepository repository, Out<GeneratedPeriods> generated) {
        String id = sheetId.trim();
        repository.lockSheet(id);
        List<Period> existing = new ArrayList<>(repository.list(id));
        List<Period> made = new ArrayList<>();
        for (YearMonth month = input.first(); !month.isAfter(input.last()); month = month.plusMonths(1)) {
            String name = month.toString();
            LocalDate from = month.atDay(1);
            LocalDate to = month.atEndOfMonth();
            boolean taken = existing.stream()
                    .anyMatch(p -> p.name().trim().equalsIgnoreCase(name) || p.overlaps(from, to));
            if (taken) {
                continue;
            }
            Period period = repository.insert(id, name, from, to);
            existing.add(period);
            made.add(period);
        }
        generated.set(new GeneratedPeriods(made));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Record each generated period in the audit file as an add, in month order. */
public class AuditPeriodsGenerated {
    public void audit(@Val PeriodGenerateInput input, @Val GeneratedPeriods generated, Audit audit) {
        for (Period period : generated.periods()) {
            audit.record("PERIOD_ADDED sheet=" + period.sheetId() + " by=" + input.user()
                    + " period=" + period.name() + " from=" + period.from() + " to=" + period.to());
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPeriodsGenerated {
    public void respond(@Val GeneratedPeriods generated, ObjectResponse<PeriodGenerateResponse> response) {
        response.send(new PeriodGenerateResponse(generated.periods().size()));
    }
}

